import {DatabaseSync} from 'node:sqlite';
import {readFileSync,readdirSync} from 'node:fs';
import {createBoardStore} from '../../lib/board-store';
import {deploymentConfig} from '../../lib/deployment-config';
import {fixtureCards as seedCards} from './cards';
export function fixture(config=deploymentConfig,legacy=false){const sqlite=new DatabaseSync(':memory:');const migrations=readdirSync('drizzle').filter(f=>f.endsWith('.sql')).sort();sqlite.exec(readFileSync(`drizzle/${migrations[0]}`,'utf8'));if(legacy)sqlite.prepare('INSERT INTO cards (id,data,version,updated_at) VALUES (?,?,?,?)').run(seedCards[0].id,JSON.stringify(seedCards[0]),7,'2026-10-26T10:00:00Z');for(const f of migrations.slice(1))sqlite.exec(readFileSync(`drizzle/${f}`,'utf8'));const db={prepare(sql:string){let args:unknown[]=[];return {bind(...v:unknown[]){args=v;return this;},execute(){const r=sqlite.prepare(sql).run(...args as []);return {meta:{changes:Number(r.changes)}};},async run(){return this.execute();},async first(){return sqlite.prepare(sql).get(...args as [])??null;},async all(){return {results:sqlite.prepare(sql).all(...args as [])};}}},async batch(statements:{execute:()=>unknown}[]){sqlite.exec('BEGIN');try{const result=statements.map(s=>s.execute());sqlite.exec('COMMIT');return result;}catch(e){sqlite.exec('ROLLBACK');throw e;}}};return {s:createBoardStore(db as unknown as D1Database,config),sqlite};}
